import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import Login from './pages/Login';
import PatientDashboard from './pages/PatientDashboard';
import PatientAppointments from './pages/PatientAppointments';
import PatientDoctors from './pages/PatientDoctors';
import PatientProfile from './pages/PatientProfile';
import PatientChat from './pages/PatientChat';
import DoctorDashboard from './pages/DoctorDashboard';
import DoctorAppointments from './pages/DoctorAppointments';
import DoctorSchedule from './pages/DoctorSchedule';
import DoctorPatients from './pages/DoctorPatients';
import DoctorProfile from './pages/DoctorProfile';
import DoctorChat from './pages/DoctorChat';
import AdminDashboard from './pages/AdminDashboard';
import AdminUsers from './pages/AdminUsers';
import AdminDoctors from './pages/AdminDoctors';
import AdminAppointments from './pages/AdminAppointments';
import AdminReports from './pages/AdminReports';
import DashboardLayout from './pages/DashboardLayout';

// Protected Route Component
const ProtectedRoute = ({ children, allowedRoles }) => {
  const { isAuthenticated, user, loading } = useAuth();

  if (loading) {
    return <div>Loading...</div>;
  }

  if (!isAuthenticated) {
    return <Navigate to="/login" replace />;
  }

  if (allowedRoles && !allowedRoles.includes(user?.role)) {
    return <Navigate to={`/${user?.role}/dashboard`} replace />;
  }

  return children;
};

// Public Route Component (redirect if already logged in)
const PublicRoute = ({ children }) => {
  const { isAuthenticated, loading } = useAuth();

  if (loading) {
    return <div>Loading...</div>;
  }

  if (isAuthenticated) {
    const role = localStorage.getItem('userRole') || 'patient';
    return <Navigate to={`/${role}/dashboard`} replace />;
  }

  return children;
};

// Page wrapper that removes DashboardLayout from individual pages
const PageWrapper = ({ children, title }) => {
  return <>{children}</>;
};

function AppRoutes() {
  const { user } = useAuth();
  const userRole = user?.role || localStorage.getItem('userRole') || 'patient';
  
  // Get page title based on route
  const getPageTitle = (pathname) => {
    const titles = {
      '/patient/dashboard': 'Patient Dashboard',
      '/patient/appointments': 'My Appointments',
      '/patient/doctors': 'Find Doctors',
      '/patient/profile': 'My Profile',
      '/patient/chat': 'AI Assistant',
      '/doctor/dashboard': 'Doctor Dashboard',
      '/doctor/appointments': 'Appointments',
      '/doctor/schedule': 'My Schedule',
      '/doctor/patients': 'Patients',
      '/doctor/profile': 'My Profile',
      '/doctor/chat': 'AI Assistant',
      '/admin/dashboard': 'Admin Dashboard',
      '/admin/users': 'Users',
      '/admin/doctors': 'Doctors',
      '/admin/appointments': 'Appointments',
      '/admin/reports': 'Reports',
    };
    return titles[pathname] || 'Dashboard';
  };

  return (
    <DashboardLayout title={getPageTitle(window.location.pathname)}>
      <Routes>
        <Route 
          path="/login" 
          element={
            <PublicRoute>
              <Login />
            </PublicRoute>
          } 
        />
        
        {/* Patient Routes */}
        <Route 
          path="/patient/dashboard" 
          element={
            <ProtectedRoute allowedRoles={['patient']}>
              <PageWrapper title="Patient Dashboard">
                <PatientDashboard />
              </PageWrapper>
            </ProtectedRoute>
          } 
        />
        <Route 
          path="/patient/appointments" 
          element={
            <ProtectedRoute allowedRoles={['patient']}>
              <PageWrapper title="My Appointments">
                <PatientAppointments />
              </PageWrapper>
            </ProtectedRoute>
          } 
        />
        <Route 
          path="/patient/doctors" 
          element={
            <ProtectedRoute allowedRoles={['patient']}>
              <PageWrapper title="Find Doctors">
                <PatientDoctors />
              </PageWrapper>
            </ProtectedRoute>
          } 
        />
        <Route 
          path="/patient/chat" 
          element={
            <ProtectedRoute allowedRoles={['patient']}>
              <PageWrapper title="AI Assistant">
                <PatientChat />
              </PageWrapper>
            </ProtectedRoute>
          } 
        />
        <Route 
          path="/patient/profile" 
          element={
            <ProtectedRoute allowedRoles={['patient']}>
              <PageWrapper title="My Profile">
                <PatientProfile />
              </PageWrapper>
            </ProtectedRoute>
