              <PageWrapper title="My Schedule">
                <DoctorSchedule />
              </PageWrapper>
            </ProtectedRoute>
          } 
        />
        <Route 
          path="/doctor/patients" 
          element={
            <ProtectedRoute allowedRoles={['doctor']}>
              <PageWrapper title="Patients">
                <DoctorPatients />
              </PageWrapper>
            </ProtectedRoute>
          } 
        />
        <Route 
          path="/doctor/chat" 
          element={
            <ProtectedRoute allowedRoles={['doctor']}>
              <PageWrapper title="AI Assistant">
                <DoctorChat />
              </PageWrapper>
            </ProtectedRoute>
          } 
        />
        <Route 
          path="/doctor/profile" 
          element={
            <ProtectedRoute allowedRoles={['doctor']}>
              <PageWrapper title="My Profile">
                <DoctorProfile />
              </PageWrapper>
            </ProtectedRoute>
          } 
        />

        {/* Admin Routes */}
        <Route 
          path="/admin/dashboard" 
          element={
            <ProtectedRoute allowedRoles={['admin']}>
              <PageWrapper title="Admin Dashboard">
                <AdminDashboard />
              </PageWrapper>
            </ProtectedRoute>
          } 
        />
        <Route 
          path="/admin/users" 
          element={
            <ProtectedRoute allowedRoles={['admin']}>
              <PageWrapper title="Users">
                <AdminUsers />
              </PageWrapper>
            </ProtectedRoute>
          } 
        />
        <Route 
          path="/admin/doctors" 
          element={
            <ProtectedRoute allowedRoles={['admin']}>
              <PageWrapper title="Doctors">
                <AdminDoctors />
              </PageWrapper>
            </ProtectedRoute>
          } 
        />
        <Route 
          path="/admin/appointments" 
          element={
            <ProtectedRoute allowedRoles={['admin']}>
              <PageWrapper title="Appointments">
                <AdminAppointments />
              </PageWrapper>
            </ProtectedRoute>
          } 
        />
        <Route 
          path="/admin/reports" 
          element={
            <ProtectedRoute allowedRoles={['admin']}>
              <PageWrapper title="Reports">
                <AdminReports />
              </PageWrapper>
            </ProtectedRoute>
          } 
        />

        {/* Default redirect */}
        <Route path="/" element={<Navigate to="/login" replace />} />
        <Route path="*" element={<Navigate to="/login" replace />} />
      </Routes>
    </DashboardLayout>
  );
}

function App() {
  return (
    <Router>
      <AuthProvider>
        <AppRoutes />
      </AuthProvider>
    </Router>
  );
}

export default App;
